-- VERDICT — 20 новых дел по мотивам классических задач для юристов и курсов этики.
-- Импорт: phpMyAdmin → ваша база → «Импорт» (или: mysql -u USER -p DBNAME < new_cases_20.sql).
-- Нужна уже работающая база сайта (таблицы создаются при первом открытии сайта).
-- Безопасно запускать повторно: дело с таким же названием второй раз не добавится.
-- Дела добавляются сразу в игру (status = 'approved') от имени команды (первый пользователь с ролью admin).
-- Чтобы сначала отправить их на отбор, замените 'approved' на 'pending'.
-- Текст дела (поле data) записан в шестнадцатеричном виде, чтобы переносы строк и кавычки не ломали JSON.

SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Стрелка на развилке (Моральные дилеммы, Частная)
INSERT INTO situations (category, type, title, author, user_id, status, data, created_at, updated_at)
SELECT 'moral', 'private', 'Стрелка на развилке', 'Команда VERDICT',
       (SELECT id FROM users WHERE role = 'admin' ORDER BY id LIMIT 1), 'approved',
       CONVERT(X'' USING utf8mb4), NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM situations WHERE title = 'Стрелка на развилке');

